import { Challenge, ChallengeSet } from "@/components/simulators/SimulatorChallengeMode";

// ═══════════════════════════════════════════════════════════════════════════════
// FISIOLOGIA HUMANA
// ═══════════════════════════════════════════════════════════════════════════════

export function getSNAChallenges(): ChallengeSet {
  return {
    title: "Desafio: Sistema Nervoso Autônomo",
    description: "Teste seus conhecimentos sobre regulação simpática e parassimpática com perguntas e ajustes práticos.",
    challenges: [
      { type: "mcq", question: "Qual neurotransmissor é liberado pelos neurônios pós-ganglionares simpáticos na maioria dos órgãos-alvo?", context: "Considere a via simpática adrenérgica clássica.", options: ["Acetilcolina", "Noradrenalina", "Dopamina", "Serotonina"], correctIndex: 1, explanation: "A noradrenalina é o principal neurotransmissor pós-ganglionar simpático. Exceção: glândulas sudoríparas écrinas (Ach).", reference: "Guyton & Hall, Cap. 60" },
      { type: "adjust", question: "Simule uma resposta vagal intensa: ajuste os tônus para obter FC < 50 bpm.", context: "O estímulo parassimpático via nervo vago reduz a FC atuando nos receptores M2 do nó SA.", targetParams: { sympathetic: { min: 0, max: 20, label: "Simpático" }, parasympathetic: { min: 70, max: 100, label: "Parassimpático" } }, validator: (s) => { const fc = s.fc ?? s.outputs?.fc; return fc < 50 ? { correct: true, feedback: "FC bradicárdica alcançada!" } : { correct: false, feedback: `FC atual: ${fc} bpm. Reduza o simpático e aumente o parassimpático.` }; }, explanation: "O tônus vagal excessivo reduz a FC via receptores M2, diminuindo a corrente If (funny current) no nó SA.", reference: "Guyton & Hall, Cap. 60" },
      { type: "mcq", question: "Qual receptor é responsável pela broncodilatação mediada pelo simpático?", options: ["α1", "β1", "β2", "M3"], correctIndex: 2, explanation: "Os receptores β2 nos brônquios causam relaxamento do músculo liso brônquico. Agonistas β2 (salbutamol) são usados na asma.", reference: "Rang & Dale, Cap. 14" },
      { type: "mcq", question: "A 'luta ou fuga' (fight-or-flight) envolve principalmente qual divisão?", options: ["Parassimpática", "Simpática", "Entérica", "Somática"], correctIndex: 1, explanation: "A resposta simpática prepara o corpo para ação: ↑FC, ↑PA, ↑glicemia, midríase, broncodilatação.", reference: "Guyton & Hall, Cap. 60" },
      { type: "adjust", question: "Reproduza uma tempestade adrenérgica: obtenha FC > 140 bpm e PAS > 180 mmHg.", context: "Feocromocitoma causa descarga simpática maciça.", targetParams: { sympathetic: { min: 85, max: 100, label: "Simpático" }, parasympathetic: { min: 0, max: 15, label: "Parassimpático" } }, validator: (s) => { const fc = s.fc ?? s.outputs?.fc; const pas = s.pas ?? s.outputs?.pas; return (fc > 140 && pas > 180) ? { correct: true, feedback: "Tempestade adrenérgica reproduzida!" } : { correct: false, feedback: `FC: ${fc}, PAS: ${pas}. Maximize o simpático.` }; }, explanation: "A ativação α1 causa vasoconstrição; β1 aumenta FC e contratilidade. No feocromocitoma, α-bloqueio antes de β-bloqueio.", reference: "Harrison's, Cap. 381" },
      { type: "mcq", question: "O reflexo barorreceptor responde à hipertensão aguda com:", options: ["↑Simpático, ↓Parassimpático", "↓Simpático, ↑Parassimpático", "↑Simpático, ↑Parassimpático", "↓Simpático, ↓Parassimpático"], correctIndex: 1, explanation: "Os barorreceptores carotídeos detectam ↑PA e ativam o centro cardioinibitório (vagal), causando bradicardia e vasodilatação.", reference: "Guyton & Hall, Cap. 18" },
      { type: "mcq", question: "Qual efeito o parassimpático tem sobre a motilidade gastrointestinal?", options: ["Diminui", "Aumenta", "Não tem efeito", "Causa espasmo apenas"], correctIndex: 1, explanation: "O parassimpático (via vago) aumenta peristaltismo, secreções e relaxa esfíncteres GI. O simpático faz o oposto.", reference: "Guyton & Hall, Cap. 62" },
      { type: "adjust", question: "Encontre o equilíbrio: ajuste para FC entre 65-75 bpm (repouso normal).", targetParams: { sympathetic: { min: 30, max: 50, label: "Simpático" }, parasympathetic: { min: 40, max: 60, label: "Parassimpático" } }, validator: (s) => { const fc = s.fc ?? s.outputs?.fc; return (fc >= 65 && fc <= 75) ? { correct: true, feedback: "Equilíbrio autonômico normal!" } : { correct: false, feedback: `FC: ${fc} bpm. Ajuste fino dos tônus.` }; }, explanation: "Em repouso, o tônus parassimpático predomina levemente, mantendo FC entre 60-80 bpm.", reference: "Guyton & Hall, Cap. 10" },
      { type: "mcq", question: "A midríase (dilatação pupilar) é mediada por qual receptor simpático?", options: ["β1", "β2", "α1", "M3"], correctIndex: 2, explanation: "Receptores α1 no músculo radial da íris causam contração e midríase. A miose é mediada por M3 (parassimpático) no músculo esfíncter.", reference: "Rang & Dale, Cap. 13" },
      { type: "mcq", question: "Qual fármaco bloqueia seletivamente o parassimpático?", options: ["Propranolol", "Fenilefrina", "Atropina", "Noradrenalina"], correctIndex: 2, explanation: "Atropina é um antagonista muscarínico competitivo (M1-M5). Bloqueia efeitos parassimpáticos: taquicardia, midríase, boca seca.", reference: "Rang & Dale, Cap. 13" },
    ],
  };
}

export function getEletrofisiologiaCardiacaChallenges(): ChallengeSet {
  return {
    title: "Desafio: Eletrofisiologia Cardíaca",
    description: "Teste conceitos sobre potencial de ação cardíaco, canais iônicos e antiarrítmicos.",
    challenges: [
      { type: "mcq", question: "Qual corrente é responsável pela fase 0 do potencial de ação ventricular?", options: ["ICa-L (cálcio tipo L)", "INa (sódio rápido)", "IK1 (potássio retificador)", "If (funny current)"], correctIndex: 1, explanation: "A fase 0 ventricular depende da entrada rápida de Na⁺ (INa). Nas células nodais, a fase 0 depende de ICa-L.", reference: "Katzung, Cap. 14" },
      { type: "adjust", question: "Simule um bloqueador de canal de Na⁺ (Classe I): reduza a condutância de Na⁺ para <40%.", context: "Antiarrítmicos Classe I (lidocaína, procainamida) bloqueiam INa, alargando a fase 0.", targetParams: { na: { min: 0, max: 40, label: "Condutância Na⁺" } }, validator: (s) => { const na = s.na ?? 100; return na <= 40 ? { correct: true, feedback: "Bloqueio de Na⁺ aplicado!" } : { correct: false, feedback: `Na⁺ em ${na}%. Reduza para ≤40%.` }; }, explanation: "O bloqueio de INa reduz a velocidade de despolarização (Vmax da fase 0) e a velocidade de condução, útil em taquicardias ventriculares.", reference: "Katzung, Cap. 14" },
      { type: "mcq", question: "A fase 2 (plateau) do PA ventricular é mantida por:", options: ["Entrada de Na⁺", "Equilíbrio entre ICa-L e IKr", "Saída de Cl⁻", "Entrada de K⁺"], correctIndex: 1, explanation: "O plateau resulta do equilíbrio entre a entrada de Ca²⁺ (ICa-L) e a saída de K⁺ (IKr), mantendo o potencial estável.", reference: "Guyton & Hall, Cap. 10" },
      { type: "mcq", question: "Qual antiarrítmico prolonga o intervalo QT ao bloquear IKr?", options: ["Lidocaína (Classe Ib)", "Amiodarona (Classe III)", "Verapamil (Classe IV)", "Atropina"], correctIndex: 1, explanation: "Classe III (amiodarona, sotalol) bloqueiam canais de K⁺ (IKr), prolongando a repolarização (fase 3) e o QT. Risco de Torsades de Pointes.", reference: "Katzung, Cap. 14" },
      { type: "adjust", question: "Simule verapamil em célula nodal: reduza Ca²⁺ para <40% e observe a bradicardia.", targetParams: { ca: { min: 0, max: 40, label: "Condutância Ca²⁺" } }, validator: (s) => { const ca = s.ca ?? 100; return ca <= 40 ? { correct: true, feedback: "Bloqueio de Ca²⁺ aplicado — frequência nodal reduzida!" } : { correct: false, feedback: `Ca²⁺ em ${ca}%. Reduza para ≤40%.` }; }, explanation: "Nas células nodais, a fase 0 depende de ICa-L. Verapamil reduz a automaticidade e a condução AV.", reference: "Katzung, Cap. 14" },
      { type: "mcq", question: "A corrente funny (If) é importante para:", options: ["Contração ventricular", "Automaticidade do nó SA", "Condução no feixe de His", "Repolarização atrial"], correctIndex: 1, explanation: "If é ativada pela hiperpolarização no nó SA (fase 4), gerando despolarização lenta espontânea. Ivabradina bloqueia seletivamente If.", reference: "Guyton & Hall, Cap. 10" },
      { type: "mcq", question: "A hipercalemia pode causar:", options: ["Prolongamento do QT", "Ondas T apiculadas", "Taquicardia sinusal", "Encurtamento do PR"], correctIndex: 1, explanation: "K⁺ elevado reduz o gradiente transmembrana, causando ondas T apiculadas, alargamento do QRS e eventualmente fibrilação/assistolia.", reference: "Harrison's, Cap. 63" },
      { type: "adjust", question: "Simule hipocalemia: aumente K⁺ a 100% e Na⁺ a 100%. Observe o PA normal e depois reduza K⁺.", targetParams: { k: { min: 50, max: 100, label: "Condutância K⁺" } }, validator: (s) => { const k = s.k ?? 100; return k >= 80 ? { correct: true, feedback: "Condutância K⁺ normal-alta restaurada!" } : { correct: false, feedback: `K⁺ em ${k}%.` }; }, explanation: "A condutância de K⁺ determina o potencial de repouso e a repolarização. Alterações de K⁺ sérico afetam diretamente o ECG.", reference: "Guyton & Hall, Cap. 10" },
      { type: "mcq", question: "Qual classe de antiarrítmico é mais segura na IC com fração de ejeção reduzida?", options: ["Classe Ia (procainamida)", "Classe Ic (flecainida)", "Classe III (amiodarona)", "Classe I (genérica)"], correctIndex: 2, explanation: "A amiodarona é o antiarrítmico mais seguro na ICFEr. Classe Ic (flecainida) é contraindicada por aumento de mortalidade (CAST trial).", reference: "ESC Guidelines 2021" },
      { type: "mcq", question: "O período refratário efetivo protege contra:", options: ["Bradicardia", "Reentrada", "Bloqueio AV", "Insuficiência cardíaca"], correctIndex: 1, explanation: "O período refratário impede que um estímulo prematuro inicie um circuito de reentrada, principal mecanismo de arritmias sustentadas.", reference: "Guyton & Hall, Cap. 13" },
    ],
  };
}

export function getDepuracaoRenalChallenges(): ChallengeSet {
  return {
    title: "Desafio: Depuração Renal",
    description: "Explore conceitos de TFG, arteríolas renais e estados clínicos que afetam a filtração glomerular.",
    challenges: [
      { type: "mcq", question: "A TFG é primariamente determinada por:", options: ["Pressão oncótica tubular", "Pressão hidrostática glomerular", "Fluxo plasmático renal apenas", "Concentração de creatinina"], correctIndex: 1, explanation: "A pressão hidrostática glomerular (~60 mmHg) é a principal força motriz da filtração. É oposta pela pressão oncótica (~32 mmHg) e pressão capsular (~18 mmHg).", reference: "Guyton & Hall, Cap. 26" },
      { type: "adjust", question: "Simule estenose da artéria renal: reduza a pressão aferente para <40% e observe a queda da TFG.", targetParams: { afferent: { min: 0, max: 40, label: "Arteríola Aferente" } }, validator: (s) => { const af = s.afferent ?? 60; return af <= 40 ? { correct: true, feedback: "Estenose simulada — TFG reduzida!" } : { correct: false, feedback: `Aferente em ${af}%. Reduza para ≤40%.` }; }, explanation: "A estenose da artéria renal reduz a pressão hidrostática no glomérulo. O rim ativa o SRAA compensatoriamente.", reference: "Guyton & Hall, Cap. 26" },
      { type: "mcq", question: "Os IECAs podem piorar a TFG em estenose bilateral porque:", options: ["Dilatam a arteríola aferente", "Dilatam a arteríola eferente", "Contraem a arteríola aferente", "Aumentam a pressão oncótica"], correctIndex: 1, explanation: "A angiotensina II mantém a TFG na estenose via constrição eferente. IECAs removem essa compensação, causando queda da TFG.", reference: "Harrison's, Cap. 298" },
      { type: "adjust", question: "Simule desidratação: reduza a hidratação para <30% e observe o impacto.", targetParams: { hydration: { min: 0, max: 30, label: "Hidratação" } }, validator: (s) => { const h = s.hydration ?? 70; return h <= 30 ? { correct: true, feedback: "Desidratação simulada!" } : { correct: false, feedback: `Hidratação em ${h}%. Reduza para ≤30%.` }; }, explanation: "A desidratação reduz o volume plasmático e ativa o SRAA (vasoconstrição eferente compensatória). Pode causar IRA pré-renal.", reference: "Guyton & Hall, Cap. 29" },
      { type: "mcq", question: "Qual marcador é o padrão-ouro para estimar a TFG?", options: ["Ureia sérica", "Creatinina sérica", "Clearance de inulina", "Ácido úrico"], correctIndex: 2, explanation: "A inulina é filtrada livremente, não é reabsorvida nem secretada. Seu clearance = TFG verdadeira. Na prática, usa-se creatinina (CKD-EPI).", reference: "Guyton & Hall, Cap. 27" },
      { type: "mcq", question: "A AINEs podem reduzir a TFG porque:", options: ["Dilatam a eferente", "Inibem prostaglandinas vasodilatadoras renais", "Aumentam a reabsorção tubular", "Bloqueiam a aldosterona"], correctIndex: 1, explanation: "As prostaglandinas (PGE2, PGI2) dilatam a aferente. AINEs bloqueiam sua síntese, causando vasoconstrição aferente e ↓TFG.", reference: "Rang & Dale, Cap. 28" },
      { type: "mcq", question: "A fração de filtração normal é aproximadamente:", options: ["5%", "10%", "20%", "40%"], correctIndex: 2, explanation: "FF = TFG/FPR ≈ 125/625 ≈ 20%. Aumenta com constrição eferente (ATII) e diminui com constrição aferente.", reference: "Guyton & Hall, Cap. 26" },
      { type: "adjust", question: "Maximize a TFG: encontre a combinação ótima de aferente dilatada e eferente moderada.", targetParams: { afferent: { min: 80, max: 100, label: "Aferente" }, efferent: { min: 50, max: 70, label: "Eferente" } }, validator: (s) => { const af = s.afferent ?? 60; const ef = s.efferent ?? 60; return (af >= 80 && ef >= 50 && ef <= 70) ? { correct: true, feedback: "TFG otimizada!" } : { correct: false, feedback: `Ajuste: aferente ${af}%, eferente ${ef}%.` }; }, explanation: "TFG máxima: aferente dilatada (↑pressão hidrostática) + eferente moderadamente constrita (mantém pressão no glomérulo).", reference: "Guyton & Hall, Cap. 26" },
      { type: "mcq", question: "Na síndrome nefrótica, a TFG pode inicialmente manter-se porque:", options: ["↑Pressão oncótica", "↓Pressão oncótica reduz a oposição à filtração", "↑Reabsorção tubular compensatória", "↑Secreção de creatinina"], correctIndex: 1, explanation: "A perda de proteínas (↓pressão oncótica) reduz a força oposta à filtração, podendo manter ou até aumentar a TFG inicialmente.", reference: "Harrison's, Cap. 308" },
      { type: "mcq", question: "A autorregulação renal mantém a TFG estável entre que valores de PA média?", options: ["40-80 mmHg", "60-120 mmHg", "80-180 mmHg", "100-200 mmHg"], correctIndex: 2, explanation: "Mecanismos miogênico e de feedback tubuloglomerular mantêm TFG entre PAM 80-180 mmHg. Abaixo de 80, a TFG cai linearmente.", reference: "Guyton & Hall, Cap. 26" },
    ],
  };
}

export function getEquilibrioAcidoBaseChallenges(): ChallengeSet {
  return {
    title: "Desafio: Equilíbrio Ácido-Base",
    description: "Interprete gasometrias, identifique distúrbios e simule correções.",
    challenges: [
      { type: "mcq", question: "pH 7.28, pCO₂ 55, HCO₃⁻ 26. Qual o distúrbio primário?", options: ["Acidose metabólica", "Alcalose metabólica", "Acidose respiratória", "Alcalose respiratória"], correctIndex: 2, explanation: "pH baixo + pCO₂ elevado = acidose respiratória. O HCO₃⁻ ligeiramente elevado sugere compensação renal parcial.", reference: "Guyton & Hall, Cap. 30" },
      { type: "adjust", question: "Corrija uma cetoacidose: ajuste pCO₂ e HCO₃⁻ para normalizar o pH (7.35-7.45).", targetParams: { pCO2: { min: 35, max: 45, label: "pCO₂" }, hco3: { min: 22, max: 26, label: "HCO₃⁻" } }, validator: (s) => { const ph = s.ph ?? s.pH ?? 7.4; return (ph >= 7.35 && ph <= 7.45) ? { correct: true, feedback: "pH normalizado!" } : { correct: false, feedback: `pH atual: ${ph?.toFixed?.(2) ?? ph}. Ajuste pCO₂ e HCO₃⁻.` }; }, explanation: "Na cetoacidose, restaurar HCO₃⁻ (insulina + fluidos) e permitir que a compensação respiratória normalize o pH.", reference: "Harrison's, Cap. 51" },
      { type: "mcq", question: "A fórmula de Winter é usada para:", options: ["Calcular o ânion gap", "Verificar a compensação respiratória esperada na acidose metabólica", "Corrigir o bicarbonato", "Estimar a pCO₂ alveolar"], correctIndex: 1, explanation: "Winter: pCO₂ esperada = 1.5 × HCO₃⁻ + 8 (±2). Se a pCO₂ medida for diferente, há distúrbio misto.", reference: "Harrison's, Cap. 51" },
      { type: "mcq", question: "Ânion gap elevado indica:", options: ["Perda de HCO₃⁻ por diarreia", "Acúmulo de ácidos orgânicos", "Alcalose metabólica", "Acidose respiratória crônica"], correctIndex: 1, explanation: "AG = Na⁺ - (Cl⁻ + HCO₃⁻). Normal: 8-12. Elevado em: cetoacidose, acidose lática, uremia, intoxicações (MUDPILES).", reference: "Harrison's, Cap. 51" },
      { type: "mcq", question: "pH 7.52, pCO₂ 48, HCO₃⁻ 38. Diagnóstico:", options: ["Acidose respiratória com compensação", "Alcalose metabólica com compensação respiratória", "Distúrbio misto", "Alcalose respiratória"], correctIndex: 1, explanation: "pH alto + HCO₃⁻ muito elevado = alcalose metabólica primária. pCO₂ elevada = compensação respiratória (hipoventilação).", reference: "Guyton & Hall, Cap. 30" },
      { type: "adjust", question: "Simule uma DPOC exacerbada: aumente pCO₂ e observe o pH cair.", targetParams: { pCO2: { min: 55, max: 80, label: "pCO₂" } }, validator: (s) => { const pco2 = s.pCO2 ?? s.pco2 ?? 40; return pco2 >= 55 ? { correct: true, feedback: "Hipercapnia simulada!" } : { correct: false, feedback: `pCO₂: ${pco2}. Aumente para ≥55.` }; }, explanation: "Na DPOC exacerbada, a retenção de CO₂ causa acidose respiratória aguda. Compensação renal (↑HCO₃⁻) demora 3-5 dias.", reference: "Harrison's, Cap. 286" },
      { type: "mcq", question: "O delta-delta (Δ/Δ) é útil para:", options: ["Calcular a osmolaridade", "Detectar distúrbios ácido-base mistos com AG elevado", "Medir a função renal", "Avaliar a ventilação"], correctIndex: 1, explanation: "ΔAG/ΔHCO₃⁻: <1 = acidose metabólica AG elevado + AG normal; >2 = acidose metabólica AG elevado + alcalose metabólica.", reference: "Harrison's, Cap. 51" },
      { type: "mcq", question: "A alcalose respiratória aguda é comum em:", options: ["DPOC", "Ansiedade e hiperventilação", "Vômitos prolongados", "Uso de diuréticos"], correctIndex: 1, explanation: "A hiperventilação por ansiedade reduz pCO₂ rapidamente, causando alcalose respiratória aguda (parestesias, tetania).", reference: "Harrison's, Cap. 51" },
      { type: "mcq", question: "Em qual pH a enzima fosfofrutoquinase-1 é inibida, reduzindo a glicólise?", options: ["pH > 7.5", "pH < 7.0", "pH = 7.4", "pH > 8.0"], correctIndex: 1, explanation: "A acidose intracelular (pH <7.0) inibe a PFK-1, contribuindo para a falência metabólica na acidose severa. Isso cria um ciclo vicioso.", reference: "Lehninger, Cap. 15" },
      { type: "adjust", question: "Normalize a gasometria: pH 7.38-7.42, pCO₂ 38-42, HCO₃⁻ 23-25.", targetParams: { pH: { min: 7.38, max: 7.42, label: "pH" }, pCO2: { min: 38, max: 42, label: "pCO₂" }, hco3: { min: 23, max: 25, label: "HCO₃⁻" } }, validator: (s) => { const ph = s.ph ?? s.pH ?? 7.4; return (ph >= 7.38 && ph <= 7.42) ? { correct: true, feedback: "Gasometria normal!" } : { correct: false, feedback: `pH: ${ph?.toFixed?.(2) ?? ph}. Continue ajustando.` }; }, explanation: "Valores normais: pH 7.38-7.42, pCO₂ 38-42 mmHg, HCO₃⁻ 22-26 mEq/L.", reference: "Guyton & Hall, Cap. 30" },
    ],
  };
}

export function getRegulacaoGlicemicaChallenges(): ChallengeSet {
  return {
    title: "Desafio: Regulação Glicêmica",
    description: "Teste conceitos de insulina, glucagon, resistência à insulina e homeostase da glicose.",
    challenges: [
      { type: "mcq", question: "Qual transportador de glicose é insulino-dependente no músculo esquelético?", options: ["GLUT1", "GLUT2", "GLUT4", "SGLT2"], correctIndex: 2, explanation: "GLUT4 é translocado para a membrana celular em resposta à insulina. No músculo e tecido adiposo, é o principal mecanismo de captação de glicose.", reference: "Guyton & Hall, Cap. 78" },
      { type: "adjust", question: "Simule DM1: reduza a função pancreática para <10% e observe a hiperglicemia.", targetParams: { pancreaticFunction: { min: 0, max: 10, label: "Função Pancreática" } }, validator: (s) => { const pf = s.pancreaticFunction ?? 50; return pf <= 10 ? { correct: true, feedback: "Deficiência absoluta de insulina simulada!" } : { correct: false, feedback: `Função: ${pf}%. Reduza para ≤10%.` }; }, explanation: "No DM1, a destruição autoimune das células β leva a deficiência absoluta de insulina, causando hiperglicemia e cetoacidose.", reference: "Harrison's, Cap. 396" },
      { type: "mcq", question: "A metformina atua primariamente:", options: ["Estimulando secreção de insulina", "Reduzindo a gliconeogênese hepática via AMPK", "Bloqueando SGLT2", "Aumentando a absorção intestinal"], correctIndex: 1, explanation: "A metformina ativa a AMPK, reduzindo a expressão de PEPCK e G6Pase no fígado. Não causa hipoglicemia como monoterapia.", reference: "Rang & Dale, Cap. 30" },
      { type: "mcq", question: "A resistência à insulina é caracterizada por:", options: ["↓Insulina sérica", "↑Insulina sérica com ↑glicemia", "↓Glucagon", "↑Sensibilidade dos receptores"], correctIndex: 1, explanation: "Na resistência, as células β compensam com hiperinsulinemia. Quando falham, a glicemia sobe (DM2).", reference: "Harrison's, Cap. 396" },
      { type: "adjust", question: "Simule resistência à insulina: sensibilidade <30% com função pancreática preservada.", targetParams: { insulinSensitivity: { min: 0, max: 30, label: "Sensibilidade à Insulina" } }, validator: (s) => { const is = s.insulinSensitivity ?? 50; return is <= 30 ? { correct: true, feedback: "Resistência à insulina simulada!" } : { correct: false, feedback: `Sensibilidade: ${is}%. Reduza para ≤30%.` }; }, explanation: "Com sensibilidade reduzida, os receptores GLUT4 são internalizados, reduzindo a captação muscular de glicose em até 50%.", reference: "Harrison's, Cap. 396" },
      { type: "mcq", question: "O glucagon é secretado pelas:", options: ["Células β", "Células α", "Células δ", "Células PP"], correctIndex: 1, explanation: "Células α secretam glucagon em resposta à hipoglicemia. Estimula glicogenólise e gliconeogênese hepática.", reference: "Guyton & Hall, Cap. 78" },
      { type: "mcq", question: "Qual efeito a insulina NÃO exerce?", options: ["↑Síntese proteica", "↑Lipogênese", "↑Gliconeogênese", "↑Captação de K⁺"], correctIndex: 2, explanation: "A insulina INIBE a gliconeogênese (via inibição de PEPCK e G6Pase). O glucagon é que a estimula.", reference: "Guyton & Hall, Cap. 78" },
      { type: "mcq", question: "A hemoglobina glicada (HbA1c) reflete a glicemia dos últimos:", options: ["7 dias", "30 dias", "2-3 meses", "6 meses"], correctIndex: 2, explanation: "A HbA1c reflete a glicemia média durante a vida do eritrócito (~120 dias). Alvo <7% na maioria dos diabéticos.", reference: "ADA Standards of Care 2024" },
      { type: "adjust", question: "Normalize a glicemia: ajuste para glicemia entre 70-110 mg/dL (jejum).", targetParams: { carbIntake: { min: 30, max: 50, label: "Carboidratos" }, insulinSensitivity: { min: 60, max: 90, label: "Sensibilidade" }, pancreaticFunction: { min: 70, max: 100, label: "Função Pancreática" } }, validator: (s) => { const g = s.glycemia ?? s.glicemia ?? 100; return (g >= 70 && g <= 110) ? { correct: true, feedback: "Glicemia normal de jejum!" } : { correct: false, feedback: `Glicemia: ${g} mg/dL. Ajuste os parâmetros.` }; }, explanation: "Glicemia de jejum normal: 70-99 mg/dL. Depende do equilíbrio entre insulina, glucagon e sensibilidade periférica.", reference: "ADA Standards of Care 2024" },
      { type: "mcq", question: "As incretinas (GLP-1) atuam:", options: ["Apenas no pâncreas", "No pâncreas (↑insulina) e no cérebro (↓apetite)", "Apenas no fígado", "No rim (↑excreção de glicose)"], correctIndex: 1, explanation: "GLP-1 potencia a secreção de insulina glicose-dependente, suprime glucagon, retarda esvaziamento gástrico e reduz apetite.", reference: "Rang & Dale, Cap. 30" },
    ],
  };
}

export function getEixoHPAChallenges(): ChallengeSet {
  return {
    title: "Desafio: Eixo HPA",
    description: "Explore o eixo hipotálamo-hipófise-adrenal, feedback negativo e patologias associadas.",
    challenges: [
      { type: "mcq", question: "A sequência correta do eixo HPA é:", options: ["ACTH → CRH → Cortisol", "CRH → ACTH → Cortisol", "Cortisol → CRH → ACTH", "CRH → Cortisol → ACTH"], correctIndex: 1, explanation: "Hipotálamo (CRH) → Hipófise anterior (ACTH) → Córtex adrenal (Cortisol). Feedback negativo em todos os níveis.", reference: "Guyton & Hall, Cap. 77" },
      { type: "adjust", question: "Simule supressão adrenal por corticoide exógeno: aumente o cortisol exógeno para >70%.", targetParams: { exogenousCortisol: { min: 70, max: 100, label: "Cortisol Exógeno" } }, validator: (s) => { const ec = s.exogenousCortisol ?? 0; return ec >= 70 ? { correct: true, feedback: "Eixo HPA suprimido pelo feedback negativo!" } : { correct: false, feedback: `Cortisol exógeno: ${ec}%. Aumente para ≥70%.` }; }, explanation: "Corticoides exógenos suprimem CRH e ACTH por feedback negativo, causando atrofia adrenal. Retirada abrupta → crise addisoniana.", reference: "Harrison's, Cap. 379" },
      { type: "mcq", question: "Na síndrome de Cushing ACTH-dependente, o ACTH está:", options: ["Suprimido", "Elevado", "Normal", "Indetectável"], correctIndex: 1, explanation: "Na doença de Cushing (adenoma hipofisário) ou secreção ectópica, o ACTH está elevado, estimulando as adrenais.", reference: "Harrison's, Cap. 379" },
      { type: "mcq", question: "O teste de supressão com dexametasona em dose baixa diferencia:", options: ["Cushing central de ectópico", "Cushing de pseudo-Cushing e normal", "Insuficiência primária de secundária", "Feocromocitoma de incidentaloma"], correctIndex: 1, explanation: "Dose baixa (1 mg overnight): cortisol não suprime = Cushing confirmado. Dose alta (8 mg): suprime = hipofisário; não suprime = ectópico.", reference: "Harrison's, Cap. 379" },
      { type: "adjust", question: "Simule estresse cirúrgico intenso: aumente o estresse para >80% sem cortisol exógeno.", targetParams: { stress: { min: 80, max: 100, label: "Nível de Estresse" } }, validator: (s) => { const st = s.stress ?? 0; return st >= 80 ? { correct: true, feedback: "Resposta ao estresse ativada — cortisol elevado!" } : { correct: false, feedback: `Estresse: ${st}%. Aumente para ≥80%.` }; }, explanation: "No estresse agudo, o cortisol pode elevar-se 2-5x. Essa resposta é vital para manter PA e mobilizar energia.", reference: "Guyton & Hall, Cap. 77" },
      { type: "mcq", question: "A insuficiência adrenal primária (Addison) se caracteriza por:", options: ["ACTH baixo + cortisol baixo", "ACTH alto + cortisol baixo", "ACTH alto + cortisol alto", "ACTH baixo + cortisol alto"], correctIndex: 1, explanation: "Na Addison, a destruição das adrenais reduz o cortisol. Sem feedback negativo, o ACTH sobe (e causa hiperpigmentação via MSH).", reference: "Harrison's, Cap. 379" },
      { type: "mcq", question: "O cortisol tem ritmo circadiano com pico:", options: ["À meia-noite", "Ao meio-dia", "Pela manhã (6-8h)", "À tarde (16h)"], correctIndex: 2, explanation: "O pico de cortisol ocorre entre 6-8h da manhã, com nadir à meia-noite. O cortisol noturno elevado sugere Cushing.", reference: "Guyton & Hall, Cap. 77" },
      { type: "mcq", question: "Qual fármaco inibe a 11β-hidroxilase, reduzindo a síntese de cortisol?", options: ["Dexametasona", "Metirapona", "Espironolactona", "Fludrocortisona"], correctIndex: 1, explanation: "A metirapona bloqueia a conversão de 11-desoxicortisol em cortisol. Usada no teste de reserva adrenal e no tratamento do Cushing.", reference: "Katzung, Cap. 39" },
      { type: "mcq", question: "A retirada gradual de corticoides é necessária após uso crônico porque:", options: ["Evita efeito rebote inflamatório apenas", "Permite recuperação do eixo HPA suprimido", "Previne ganho de peso", "Reduz o risco de osteoporose"], correctIndex: 1, explanation: "Após supressão prolongada, as adrenais estão atróficas e precisam de semanas/meses para recuperar. Retirada abrupta → insuficiência adrenal aguda.", reference: "Harrison's, Cap. 379" },
      { type: "mcq", question: "O hiperaldosteronismo primário (Conn) é diagnosticado por:", options: ["Teste de supressão com dexametasona", "Relação aldosterona/renina elevada", "ACTH estimulação", "Cortisol livre urinário"], correctIndex: 1, explanation: "RAR elevada (aldosterona alta + renina suprimida) é o screening. Confirmação com teste de infusão salina ou captopril.", reference: "Harrison's, Cap. 379" },
    ],
  };
}

export function getCineticaEnzimaticaChallenges(): ChallengeSet {
  return {
    title: "Desafio: Cinética Enzimática",
    description: "Michaelis-Menten, Lineweaver-Burk, tipos de inibição e aplicações clínicas.",
    challenges: [
      { type: "mcq", question: "Quando [S] = Km, a velocidade da reação é:", options: ["Vmax", "Vmax/2", "Vmax/4", "Zero"], correctIndex: 1, explanation: "Por definição, Km é a concentração de substrato na qual V = Vmax/2. Representa a afinidade da enzima pelo substrato.", reference: "Lehninger, Cap. 6" },
      { type: "mcq", question: "Na inibição competitiva, o que acontece com Km e Vmax?", options: ["Km↑, Vmax inalterado", "Km inalterado, Vmax↓", "Km↓, Vmax↓", "Km inalterado, Vmax↑"], correctIndex: 0, explanation: "O inibidor competitivo compete pelo sítio ativo, aumentando o Km aparente. Pode ser superado com excesso de substrato (Vmax inalterado).", reference: "Lehninger, Cap. 6" },
      { type: "adjust", question: "Ative a inibição competitiva e observe o Km aumentar sem alterar o Vmax.", targetParams: { km: { min: 70, max: 200, label: "Km aparente" } }, validator: (s) => { const km = s.km ?? s.effectiveKm ?? 50; return km >= 70 ? { correct: true, feedback: "Inibição competitiva demonstrada — Km↑!" } : { correct: false, feedback: `Km aparente: ${km}. Ative o inibidor competitivo.` }; }, explanation: "Na inibição competitiva, o Km aparente aumenta proporcionalmente à [I]/Ki. O gráfico de Lineweaver-Burk mostra linhas convergindo no eixo Y.", reference: "Lehninger, Cap. 6" },
      { type: "mcq", question: "No gráfico de Lineweaver-Burk, a inibição não-competitiva mostra:", options: ["Linhas paralelas", "Linhas convergindo no eixo X", "Linhas convergindo no eixo Y", "Mesma linha"], correctIndex: 1, explanation: "Não-competitiva: mesmo Km (intercepto X inalterado), Vmax↓ (intercepto Y aumentado). Linhas convergem no eixo X (-1/Km).", reference: "Lehninger, Cap. 6" },
      { type: "mcq", question: "O metotrexato é um exemplo de inibidor:", options: ["Não-competitivo", "Acompetitivo", "Competitivo", "Irreversível"], correctIndex: 2, explanation: "O metotrexato é um análogo estrutural do folato que compete pelo sítio ativo da DHFR (di-hidrofolato redutase).", reference: "Rang & Dale, Cap. 50" },
      { type: "adjust", question: "Ative a inibição não-competitiva e observe o Vmax diminuir com Km inalterado.", targetParams: { vmax: { min: 20, max: 70, label: "Vmax aparente" } }, validator: (s) => { const vmax = s.vmax ?? s.effectiveVmax ?? 100; return vmax <= 70 ? { correct: true, feedback: "Inibição não-competitiva demonstrada — Vmax↓!" } : { correct: false, feedback: `Vmax: ${vmax}. Ative o inibidor não-competitivo.` }; }, explanation: "O inibidor não-competitivo liga-se a um sítio alostérico, reduzindo a quantidade de enzima funcional sem afetar a afinidade.", reference: "Lehninger, Cap. 6" },
      { type: "mcq", question: "A alosterismo positivo causa:", options: ["↑Km, ↓Vmax", "↓Km, ↑Vmax", "↑Km, ↑Vmax", "Sem efeito"], correctIndex: 1, explanation: "Efetores alostéricos positivos aumentam a afinidade (↓Km) e podem aumentar a eficiência catalítica (↑Vmax).", reference: "Lehninger, Cap. 6" },
      { type: "mcq", question: "O cianeto inibe o Complexo IV da cadeia respiratória de forma:", options: ["Competitiva reversível", "Não-competitiva irreversível", "Acompetitiva", "Competitiva com O₂"], correctIndex: 1, explanation: "O cianeto liga-se irreversivelmente ao Fe³⁺ do citocromo a3, bloqueando a transferência de elétrons ao O₂. Tratamento: hidroxocobalamina.", reference: "Lehninger, Cap. 19" },
      { type: "mcq", question: "Enzimas alostéricas NÃO seguem a cinética de Michaelis-Menten porque:", options: ["Não têm sítio ativo", "Apresentam curva sigmoide, não hiperbólica", "Não são proteínas", "Funcionam sem substrato"], correctIndex: 1, explanation: "Enzimas alostéricas têm múltiplas subunidades com cooperatividade, resultando em curva sigmoide (coeficiente de Hill > 1).", reference: "Lehninger, Cap. 6" },
      { type: "mcq", question: "A kcat (número de turnover) representa:", options: ["Afinidade pelo substrato", "Moléculas de produto formadas por molécula de enzima por segundo", "Constante de dissociação", "Velocidade na ausência de enzima"], correctIndex: 1, explanation: "kcat = Vmax/[E]total. A eficiência catalítica é dada por kcat/Km. Valores >10⁸ M⁻¹s⁻¹ indicam 'perfeição catalítica'.", reference: "Lehninger, Cap. 6" },
    ],
  };
}

export function getSecrecaoGastricaChallenges(): ChallengeSet {
  return {
    title: "Desafio: Secreção Gástrica",
    description: "Explore as vias de secreção ácida, IBPs, anti-H2 e cenários clínicos gastroenterológicos.",
    challenges: [
      { type: "mcq", question: "A bomba de prótons (H⁺/K⁺-ATPase) é localizada nas:", options: ["Células principais", "Células parietais", "Células ECL", "Células G"], correctIndex: 1, explanation: "As células parietais contêm a H⁺/K⁺-ATPase na membrana canalicular. São estimuladas por histamina (H2), Ach (M3) e gastrina (CCK-B).", reference: "Guyton & Hall, Cap. 64" },
      { type: "mcq", question: "Os IBPs são mais eficazes que anti-H2 porque:", options: ["Bloqueiam mais receptores", "Atuam na via final comum (bomba de prótons)", "Têm maior biodisponibilidade", "São mais seletivos"], correctIndex: 1, explanation: "Os IBPs bloqueiam irreversivelmente a H⁺/K⁺-ATPase, a via final de secreção ácida, independente do estímulo. Anti-H2 bloqueiam apenas a via da histamina.", reference: "Rang & Dale, Cap. 29" },
      { type: "mcq", question: "Na síndrome de Zollinger-Ellison, o pH gástrico é extremamente baixo porque:", options: ["↑Histamina", "↑Gastrina tumoral estimulando massivamente as células parietais", "↓Bicarbonato", "↑Acetilcolina"], correctIndex: 1, explanation: "O gastrinoma secreta gastrina em níveis suprafisiológicos, estimulando diretamente as parietais e indiretamente via ECL (histamina).", reference: "Harrison's, Cap. 348" },
      { type: "mcq", question: "A prostaglandina E2 (PGE2) no estômago:", options: ["Aumenta a secreção ácida", "Protege a mucosa (↑muco, ↑bicarbonato, ↑fluxo sanguíneo)", "Estimula a pepsina", "Causa ulceração"], correctIndex: 1, explanation: "PGE2 é citoprotetora: ↑secreção de muco e bicarbonato, ↑fluxo sanguíneo mucoso, ↓secreção ácida. AINEs inibem COX e removem essa proteção.", reference: "Rang & Dale, Cap. 29" },
      { type: "mcq", question: "O Helicobacter pylori causa úlcera principalmente por:", options: ["Produção direta de ácido", "Urease + resposta inflamatória + disrupção da barreira mucosa", "Bloqueio da bomba de prótons", "Estimulação vagal"], correctIndex: 1, explanation: "H. pylori produz urease (alcaliniza microambiente), mas causa inflamação crônica, ↑gastrina, ↓somatostatina e disrupção da camada de muco.", reference: "Harrison's, Cap. 346" },
      { type: "mcq", question: "Qual célula secreta histamina no estômago?", options: ["Célula parietal", "Célula principal", "Célula ECL (enterocromafim-like)", "Célula D"], correctIndex: 2, explanation: "As células ECL liberam histamina em resposta à gastrina. A histamina atua nos receptores H2 das células parietais (via parácrina).", reference: "Guyton & Hall, Cap. 64" },
      { type: "mcq", question: "O omeprazol deve ser tomado:", options: ["Após as refeições", "30 min antes da primeira refeição do dia", "Ao deitar", "Com antiácidos"], correctIndex: 1, explanation: "IBPs são pró-fármacos ativados em meio ácido. Devem ser tomados em jejum 30 min antes da refeição, quando as bombas são ativadas pela alimentação.", reference: "Rang & Dale, Cap. 29" },
      { type: "mcq", question: "A somatostatina (célula D) no estômago:", options: ["Estimula a secreção ácida", "Inibe gastrina, histamina e secreção ácida", "Estimula a pepsina", "Não tem função"], correctIndex: 1, explanation: "A somatostatina é o 'freio' fisiológico: inibe células G (gastrina), ECL (histamina) e parietais (ácido). Feedback negativo.", reference: "Guyton & Hall, Cap. 64" },
      { type: "mcq", question: "A vagotomia reduz a secreção ácida porque:", options: ["Bloqueia apenas a histamina", "Remove o estímulo colinérgico (Ach) direto e indireto (via gastrina)", "Destrói as células parietais", "Aumenta a somatostatina"], correctIndex: 1, explanation: "O vago estimula diretamente as parietais (M3) e as células G (gastrina). A vagotomia troncular reduz ~70% da secreção ácida.", reference: "Guyton & Hall, Cap. 64" },
      { type: "mcq", question: "O uso crônico de IBPs pode causar:", options: ["Nenhum efeito adverso", "Hipomagnesemia, ↓absorção de Ca²⁺/Fe, risco de C. difficile", "Hemorragia GI", "Hepatotoxicidade"], correctIndex: 1, explanation: "Uso prolongado de IBPs: ↓absorção de Mg²⁺, Ca²⁺, Fe, B12; ↑risco de infecções intestinais (C. difficile) e fraturas osteoporóticas.", reference: "Harrison's, Cap. 346" },
    ],
  };
}

export function getCascataCoagulacaoChallenges(): ChallengeSet {
  return {
    title: "Desafio: Cascata de Coagulação",
    description: "Vias intrínseca, extrínseca e comum; anticoagulantes e coagulopatias.",
    challenges: [
      { type: "mcq", question: "O TP (tempo de protrombina) avalia principalmente:", options: ["Via intrínseca", "Via extrínseca e comum", "Fibrinólise", "Função plaquetária"], correctIndex: 1, explanation: "O TP avalia os fatores VII (extrínseca) + X, V, II, I (via comum). É prolongado por varfarina e deficiência de vitamina K.", reference: "Harrison's, Cap. 112" },
      { type: "mcq", question: "Na hemofilia A, qual teste está prolongado?", options: ["TP", "TTPa", "Tempo de sangramento", "INR"], correctIndex: 1, explanation: "A hemofilia A (deficiência de FVIII) prolonga o TTPa (via intrínseca). O TP e INR permanecem normais.", reference: "Harrison's, Cap. 112" },
      { type: "mcq", question: "A varfarina afeta os fatores:", options: ["VIII e IX apenas", "II, VII, IX e X (vitamina K-dependentes)", "I e V apenas", "Todos os fatores"], correctIndex: 1, explanation: "A varfarina inibe a VKOR (vitamina K epóxido redutase), afetando a carboxilação dos fatores II, VII, IX, X e proteínas C e S.", reference: "Katzung, Cap. 34" },
      { type: "mcq", question: "Na CIVD, o que ocorre com TP e TTPa?", options: ["Ambos normais", "TP prolongado, TTPa normal", "TP normal, TTPa prolongado", "Ambos prolongados"], correctIndex: 3, explanation: "Na CIVD, o consumo maciço de fatores de coagulação prolonga tanto TP quanto TTPa. Fibrinogênio↓, D-dímero↑, plaquetas↓.", reference: "Harrison's, Cap. 112" },
      { type: "mcq", question: "O INR terapêutico para FA não-valvular é:", options: ["1.0-1.5", "2.0-3.0", "3.0-4.0", "4.0-5.0"], correctIndex: 1, explanation: "INR 2.0-3.0 para FA, TVP/TEP. INR 2.5-3.5 para próteses valvulares mecânicas.", reference: "ESC Guidelines 2020" },
      { type: "mcq", question: "A heparina não fracionada (HNF) atua potenciando:", options: ["A vitamina K", "A antitrombina III", "O fator XIII", "A proteína C"], correctIndex: 1, explanation: "A HNF liga-se à antitrombina III, potenciando sua ação inibitória sobre trombina (IIa) e Xa em ~1000x. Monitorizada pelo TTPa.", reference: "Katzung, Cap. 34" },
      { type: "mcq", question: "O antídoto da heparina é:", options: ["Vitamina K", "Protamina", "Ácido aminocaproico", "Desmopressina"], correctIndex: 1, explanation: "Protamina forma complexo iônico com heparina, neutralizando sua atividade anticoagulante. 1 mg neutraliza ~100 UI de HNF.", reference: "Katzung, Cap. 34" },
      { type: "mcq", question: "A via extrínseca é iniciada pelo:", options: ["Contato com colágeno", "Fator tecidual (tromboplastina) + FVII", "Cininogênio de alto peso molecular", "Cálcio iônico"], correctIndex: 1, explanation: "Lesão vascular expõe o fator tecidual (TF), que se liga ao FVII e ativa a via extrínseca. É o iniciador fisiológico in vivo.", reference: "Harrison's, Cap. 112" },
      { type: "mcq", question: "O D-dímero elevado indica:", options: ["Coagulação ativa", "Fibrinólise (degradação de fibrina)", "Deficiência de FVIII", "Trombocitopenia"], correctIndex: 1, explanation: "D-dímero é produto da degradação da fibrina entrecruzada por plasmina. Elevado em TVP/TEP, CIVD, pós-operatório. Alto VPN para exclusão de TEP.", reference: "Harrison's, Cap. 273" },
      { type: "mcq", question: "A trombocitopenia induzida por heparina (HIT) tipo II é mediada por:", options: ["Efeito tóxico direto", "Anticorpos anti-PF4/heparina", "Deficiência de AT-III", "Consumo por CIVD"], correctIndex: 1, explanation: "HIT tipo II: anticorpos IgG contra complexo PF4/heparina ativam plaquetas, causando trombocitopenia paradoxal COM trombose. Suspender heparina!", reference: "Harrison's, Cap. 112" },
    ],
  };
}

export function getADMEChallenges(): ChallengeSet {
  return {
    title: "Desafio: Farmacocinética (ADME)",
    description: "Absorção, distribuição, metabolismo e excreção de fármacos.",
    challenges: [
      { type: "mcq", question: "A biodisponibilidade oral é reduzida principalmente pelo:", options: ["Volume de distribuição", "Metabolismo de primeira passagem hepática", "Clearance renal", "Ligação a proteínas plasmáticas"], correctIndex: 1, explanation: "O efeito de primeira passagem (metabolismo hepático e intestinal) é o principal fator que reduz a biodisponibilidade oral.", reference: "Katzung, Cap. 3" },
      { type: "adjust", question: "Simule um fármaco com alta extração hepática: aumente a primeira passagem e observe Cmax cair.", targetParams: { bioavailability: { min: 10, max: 35, label: "Biodisponibilidade" } }, validator: (s) => { const b = s.bioavailability ?? 50; return b <= 35 ? { correct: true, feedback: "Alta extração hepática simulada — baixa biodisponibilidade!" } : { correct: false, feedback: `Biodisponibilidade: ${b}%. Reduza para ≤35%.` }; }, explanation: "Fármacos com alta extração hepática (>70%): lidocaína, propranolol, morfina. Via oral impraticável → usar IV, SL ou transdérmica.", reference: "Katzung, Cap. 3" },
      { type: "mcq", question: "O volume de distribuição (Vd) elevado indica:", options: ["Fármaco retido no plasma", "Extensa distribuição tecidual", "Alta ligação a albumina", "Rápida excreção renal"], correctIndex: 1, explanation: "Vd alto = fármaco se distribui amplamente nos tecidos. Digoxina Vd~500L, cloroquina Vd~13000L. Vd baixo (heparina ~5L) = plasma apenas.", reference: "Katzung, Cap. 3" },
      { type: "mcq", question: "A meia-vida de eliminação depende de:", options: ["Apenas do clearance", "Apenas do Vd", "Vd e clearance (t½ = 0.693 × Vd/CL)", "Apenas da biodisponibilidade"], correctIndex: 2, explanation: "t½ = 0.693 × Vd/CL. Vd↑ ou CL↓ = t½ mais longa. O estado estacionário é atingido após ~5 meias-vidas.", reference: "Katzung, Cap. 3" },
      { type: "adjust", question: "Simule digoxina: alto Vd (>90%) e baixo clearance (<15%) para observar meia-vida longa.", targetParams: { vd: { min: 90, max: 100, label: "Vd" }, clearance: { min: 5, max: 15, label: "Clearance" } }, validator: (s) => { const vd = s.vd ?? 50; const cl = s.clearance ?? 20; return (vd >= 90 && cl <= 15) ? { correct: true, feedback: "Perfil da digoxina simulado — meia-vida longa!" } : { correct: false, feedback: `Vd: ${vd}%, CL: ${cl}%. Ajuste.` }; }, explanation: "Digoxina: Vd ~500L (extensa ligação tecidual), CL baixo. T½ ~36-48h. Risco de toxicidade em insuficiência renal.", reference: "Katzung, Cap. 3" },
      { type: "mcq", question: "O citocromo P450 mais importante no metabolismo de fármacos é:", options: ["CYP1A2", "CYP2C19", "CYP3A4", "CYP2E1"], correctIndex: 2, explanation: "CYP3A4 metaboliza ~50% de todos os fármacos. Indutores: rifampicina, carbamazepina. Inibidores: cetoconazol, eritromicina, suco de toranja.", reference: "Katzung, Cap. 4" },
      { type: "mcq", question: "O estado estacionário é atingido após:", options: ["1 meia-vida", "3 meias-vidas", "~5 meias-vidas", "10 meias-vidas"], correctIndex: 2, explanation: "Após 5 t½, ~97% do estado estacionário é atingido. Para fármacos com t½ longa, pode ser necessária dose de ataque.", reference: "Katzung, Cap. 3" },
      { type: "mcq", question: "A ligação a proteínas plasmáticas (albumina):", options: ["Aumenta o efeito farmacológico", "Reduz a fração livre (ativa) do fármaco", "Acelera a excreção renal", "Não tem significado clínico"], correctIndex: 1, explanation: "Apenas a fração livre é farmacologicamente ativa e pode ser filtrada. Em hipoalbuminemia, a fração livre aumenta → risco de toxicidade.", reference: "Katzung, Cap. 3" },
      { type: "mcq", question: "A dose de ataque é calculada como:", options: ["Dose × clearance", "Css × Vd / F", "Dose / biodisponibilidade", "CL × t½"], correctIndex: 1, explanation: "Dose de ataque = Css-alvo × Vd / F. Para atingir rapidamente a concentração terapêutica sem esperar 5 t½.", reference: "Katzung, Cap. 3" },
      { type: "mcq", question: "A excreção renal de fármacos ionizados depende do:", options: ["Peso molecular apenas", "pH urinário (ion trapping)", "Volume de distribuição", "Metabolismo hepático"], correctIndex: 1, explanation: "Fármacos ácidos fracos são mais excretados em urina alcalina (ionizados, não reabsorvidos). Usado na intoxicação por salicilatos (alcalinização urinária).", reference: "Katzung, Cap. 3" },
    ],
  };
}

